    <link rel='stylesheet' id='dashicons-css'
        href='https://www.jualkubahmasjid.id/wp-includes/css/dashicons.min.css?ver=6.9.4' media='all' />
    <link rel='stylesheet' id='admin-bar-css'
        href='https://www.jualkubahmasjid.id/wp-includes/css/admin-bar.min.css?ver=6.9.4' media='all' />
    <style id='admin-bar-inline-css'>
        /* Hide CanvasJS credits for P404 charts specifically */
        #p404RedirectChart .canvasjs-chart-credit {
            display: none !important;
        }

        #p404RedirectChart canvas {
            border-radius: 6px;
        }

        .p404-redirect-adminbar-weekly-title {
            font-weight: bold;
            font-size: 14px;
            color: #fff;
            margin-bottom: 6px;
        }

        #wpadminbar #wp-admin-bar-p404_free_top_button .ab-icon:before {
            content: "\f103";
            color: #dc3545;
            top: 3px;
        }

        #wp-admin-bar-p404_free_top_button .ab-item {
            min-width: 80px !important;
            padding: 0px !important;
        }

        /* Ensure proper positioning and z-index for P404 dropdown */
        .p404-redirect-adminbar-dropdown-wrap {
            min-width: 0;
            padding: 0;
            position: static !important;
        }

        #wpadminbar #wp-admin-bar-p404_free_top_button_dropdown {
            position: static !important;
        }

        #wpadminbar #wp-admin-bar-p404_free_top_button_dropdown .ab-item {
            padding: 0 !important;
            margin: 0 !important;
        }

        .p404-redirect-dropdown-container {
            min-width: 340px;
            padding: 18px 18px 12px 18px;
            background: #23282d !important;
            color: #fff;
            border-radius: 12px;
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25);
            margin-top: 10px;
            position: relative !important;
            z-index: 999999 !important;
            display: block !important;
            border: 1px solid #444;
        }

        /* Ensure P404 dropdown appears on hover */
        #wpadminbar #wp-admin-bar-p404_free_top_button .p404-redirect-dropdown-container {
            display: none !important;
        }

        #wpadminbar #wp-admin-bar-p404_free_top_button:hover .p404-redirect-dropdown-container {
            display: block !important;
        }

        #wpadminbar #wp-admin-bar-p404_free_top_button:hover #wp-admin-bar-p404_free_top_button_dropdown .p404-redirect-dropdown-container {
            display: block !important;
        }

        .p404-redirect-card {
            background: #2c3338;
            border-radius: 8px;
            padding: 18px 18px 12px 18px;
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.07);
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            border: 1px solid #444;
        }

        .p404-redirect-btn {
            display: inline-block;
            background: #dc3545;
            color: #fff !important;
            font-weight: bold;
            padding: 5px 22px;
            border-radius: 8px;
            text-decoration: none;
            font-size: 17px;
            transition: background 0.2s, box-shadow 0.2s;
            margin-top: 8px;
            box-shadow: 0 2px 8px rgba(220, 53, 69, 0.15);
            text-align: center;
            line-height: 1.6;
        }

        .p404-redirect-btn:hover {
            background: #c82333;
            color: #fff !important;
            box-shadow: 0 4px 16px rgba(220, 53, 69, 0.25);
        }

        /* Prevent conflicts with other admin bar dropdowns */
        #wpadminbar .ab-top-menu>li:hover>.ab-item,
        #wpadminbar .ab-top-menu>li.hover>.ab-item {
            z-index: auto;
        }

        #wpadminbar #wp-admin-bar-p404_free_top_button:hover>.ab-item {
            z-index: 999998 !important;
        }

        /*# sourceURL=admin-bar-inline-css */
    </style>
    <link rel='stylesheet' id='hide-metadata-style-css'
        href='https://www.jualkubahmasjid.id/wp-content/plugins/hide-metadata/css/style.css?ver=2.0' media='all' />
    <link rel='stylesheet' id='eztoc-css'
        href='https://www.jualkubahmasjid.id/wp-content/plugins/easy-table-of-contents/assets/css/screen.min.css?ver=2.0.83'
        media='all' />
    <style id='eztoc-inline-css'>
        div#ez-toc-container .ez-toc-title {
            font-size: 120%;
        }

        div#ez-toc-container .ez-toc-title {
            font-weight: 500;
        }

        div#ez-toc-container ul li,
        div#ez-toc-container ul li a {
            font-size: 95%;
        }

        div#ez-toc-container ul li,
        div#ez-toc-container ul li a {
            font-weight: 500;
        }

        div#ez-toc-container nav ul ul li {
            font-size: 90%;
        }

        .ez-toc-box-title {
            font-weight: bold;
            margin-bottom: 10px;
            text-align: center;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: #666;
            padding-bottom: 5px;
            position: absolute;
            top: -4%;
            left: 5%;
            background-color: inherit;
            transition: top 0.3s ease;
        }

        .ez-toc-box-title.toc-closed {
            top: -25%;
        }

        .ez-toc-container-direction {
            direction: ltr;
        }

        .ez-toc-counter ul {
            counter-reset: item;
        }

        .ez-toc-counter nav ul li a::before {
            content: counters(item, '.', decimal) '. ';
            display: inline-block;
            counter-increment: item;
            flex-grow: 0;
            flex-shrink: 0;
            margin-right: .2em;
            float: left;
        }

        .ez-toc-widget-direction {
            direction: ltr;
        }

        .ez-toc-widget-container ul {
            counter-reset: item;
        }

        .ez-toc-widget-container nav ul li a::before {
            content: counters(item, '.', decimal) '. ';
            display: inline-block;
            counter-increment: item;
            flex-grow: 0;
            flex-shrink: 0;
            margin-right: .2em;
            float: left;
        }

        /*# sourceURL=eztoc-inline-css */
    </style>
    <link rel='stylesheet' id='generate-style-grid-css'
        href='https://www.jualkubahmasjid.id/wp-content/themes/generatepress/assets/css/unsemantic-grid.min.css?ver=3.6.1'
        media='all' />
    <link rel='stylesheet' id='generate-style-css'
        href='https://www.jualkubahmasjid.id/wp-content/themes/generatepress/assets/css/style.min.css?ver=3.6.1'
        media='all' />
    <style id='generate-style-inline-css'>
        body {
            background-color: #efefef;
            color: #3a3a3a;
        }

        a {
            color: #1e73be;
        }

        a:hover,
        a:focus,
        a:active {
            color: #000000;
        }

        body .grid-container {
            max-width: 1100px;
        }

        .wp-block-group__inner-container {
            max-width: 1100px;
            margin-left: auto;
            margin-right: auto;
        }

        :root {
            --contrast: #222222;
            --contrast-2: #575760;
            --contrast-3: #b2b2be;
            --base: #f0f0f0;
            --base-2: #f7f8f9;
            --base-3: #ffffff;
            --accent: #1e73be;
        }

        :root .has-contrast-color {
            color: var(--contrast);
        }

        :root .has-contrast-background-color {
            background-color: var(--contrast);
        }

        :root .has-contrast-2-color {
            color: var(--contrast-2);
        }

        :root .has-contrast-2-background-color {
            background-color: var(--contrast-2);
        }

        :root .has-contrast-3-color {
            color: var(--contrast-3);
        }

        :root .has-contrast-3-background-color {
            background-color: var(--contrast-3);
        }

        :root .has-base-color {
            color: var(--base);
        }

        :root .has-base-background-color {
            background-color: var(--base);
        }

        :root .has-base-2-color {
            color: var(--base-2);
        }

        :root .has-base-2-background-color {
            background-color: var(--base-2);
        }

        :root .has-base-3-color {
            color: var(--base-3);
        }

        :root .has-base-3-background-color {
            background-color: var(--base-3);
        }

        :root .has-accent-color {
            color: var(--accent);
        }

        :root .has-accent-background-color {
            background-color: var(--accent);
        }

        body,
        button,
        input,
        select,
        textarea {
            font-family: "Open Sans", sans-serif;
        }

        body {
            line-height: 1.5;
        }

        .entry-content>[class*="wp-block-"]:not(:last-child):not(.wp-block-heading) {
            margin-bottom: 1.5em;
        }

        .main-title {
            font-size: 45px;
        }

        .main-navigation .main-nav ul ul li a {
            font-size: 14px;
        }

        .sidebar .widget,
        .footer-widgets .widget {
            font-size: 17px;
        }

        h1 {
            font-weight: 300;
            font-size: 40px;
        }

        h2 {
            font-weight: 300;
            font-size: 30px;
        }

        h3 {
            font-size: 20px;
        }

        h4 {
            font-size: inherit;
        }

        h5 {
            font-size: inherit;
        }

        @media (max-width:768px) {
            .main-title {
                font-size: 30px;
            }

            h1 {
                font-size: 30px;
            }

            h2 {
                font-size: 25px;
            }
        }

        .top-bar {
            background-color: #636363;
            color: #ffffff;
        }

        .top-bar a {
            color: #ffffff;
        }

        .top-bar a:hover {
            color: #303030;
        }

        .site-header {
            background-color: #ffffff;
            color: #3a3a3a;
        }

        .site-header a {
            color: #3a3a3a;
        }

        .main-title a,
        .main-title a:hover {
            color: #222222;
        }

        .site-description {
            color: #757575;
        }

        .main-navigation,
        .main-navigation ul ul {
            background-color: #222222;
        }

        .main-navigation .main-nav ul li a,
        .main-navigation .menu-toggle,
        .main-navigation .menu-bar-items {
            color: #ffffff;
        }

        .main-navigation .main-nav ul li:not([class*="current-menu-"]):hover>a,
        .main-navigation .main-nav ul li:not([class*="current-menu-"]):focus>a,
        .main-navigation .main-nav ul li.sfHover:not([class*="current-menu-"])>a,
        .main-navigation .menu-bar-item:hover>a,
        .main-navigation .menu-bar-item.sfHover>a {
            color: #ffffff;
            background-color: #3f3f3f;
        }

        button.menu-toggle:hover,
        button.menu-toggle:focus,
        .main-navigation .mobile-bar-items a,
        .main-navigation .mobile-bar-items a:hover,
        .main-navigation .mobile-bar-items a:focus {
            color: #ffffff;
        }

        .main-navigation .main-nav ul li[class*="current-menu-"]>a {
            color: #ffffff;
            background-color: #3f3f3f;
        }

        .navigation-search input[type="search"],
        .navigation-search input[type="search"]:active,
        .navigation-search input[type="search"]:focus,
        .main-navigation .main-nav ul li.search-item.active>a,
        .main-navigation .menu-bar-items .search-item.active>a {
            color: #ffffff;
            background-color: #3f3f3f;
        }

        .main-navigation ul ul {
            background-color: #3f3f3f;
        }

        .main-navigation .main-nav ul ul li a {
            color: #ffffff;
        }

        .main-navigation .main-nav ul ul li:not([class*="current-menu-"]):hover>a,
        .main-navigation .main-nav ul ul li:not([class*="current-menu-"]):focus>a,
        .main-navigation .main-nav ul ul li.sfHover:not([class*="current-menu-"])>a {
            color: #ffffff;
            background-color: #4f4f4f;
        }

        .main-navigation .main-nav ul ul li[class*="current-menu-"]>a {
            color: #ffffff;
            background-color: #4f4f4f;
        }

        .separate-containers .inside-article,
        .separate-containers .comments-area,
        .separate-containers .page-header,
        .one-container .container,
        .separate-containers .paging-navigation,
        .inside-page-header {
            background-color: #ffffff;
        }

        .entry-meta {
            color: #595959;
        }

        .entry-meta a {
            color: #595959;
        }

        .entry-meta a:hover {
            color: #1e73be;
        }

        .sidebar .widget {
            background-color: #ffffff;
        }

        .sidebar .widget .widget-title {
            color: #000000;
        }

        .footer-widgets {
            background-color: #ffffff;
        }

        .footer-widgets .widget-title {
            color: #000000;
        }

        .site-info {
            color: #ffffff;
            background-color: #222222;
        }

        .site-info a {
            color: #ffffff;
        }

        .site-info a:hover {
            color: #606060;
        }

        .footer-bar .widget_nav_menu .current-menu-item a {
            color: #606060;
        }

        input[type="text"],
        input[type="email"],
        input[type="url"],
        input[type="password"],
        input[type="search"],
        input[type="tel"],
        input[type="number"],
        textarea,
        select {
            color: #666666;
            background-color: #fafafa;
            border-color: #cccccc;
        }

        input[type="text"]:focus,
        input[type="email"]:focus,
        input[type="url"]:focus,
        input[type="password"]:focus,
        input[type="search"]:focus,
        input[type="tel"]:focus,
        input[type="number"]:focus,
        textarea:focus,
        select:focus {
            color: #666666;
            background-color: #ffffff;
            border-color: #bfbfbf;
        }

        button,
        html input[type="button"],
        input[type="reset"],
        input[type="submit"],
        a.button,
        a.wp-block-button__link:not(.has-background) {
            color: #ffffff;
            background-color: #666666;
        }

        button:hover,
        html input[type="button"]:hover,
        input[type="reset"]:hover,
        input[type="submit"]:hover,
        a.button:hover,
        button:focus,
        html input[type="button"]:focus,
        input[type="reset"]:focus,
        input[type="submit"]:focus,
        a.button:focus,
        a.wp-block-button__link:not(.has-background):active,
        a.wp-block-button__link:not(.has-background):focus,
        a.wp-block-button__link:not(.has-background):hover {
            color: #ffffff;
            background-color: #3f3f3f;
        }

        a.generate-back-to-top {
            background-color: rgba(0, 0, 0, 0.4);
            color: #ffffff;
        }

        a.generate-back-to-top:hover,
        a.generate-back-to-top:focus {
            background-color: rgba(0, 0, 0, 0.6);
            color: #ffffff;
        }

        :root {
            --gp-search-modal-bg-color: var(--base-3);
            --gp-search-modal-text-color: var(--contrast);
            --gp-search-modal-overlay-bg-color: rgba(0, 0, 0, 0.2);
        }

        @media (max-width:768px) {

            .main-navigation .menu-bar-item:hover>a,
            .main-navigation .menu-bar-item.sfHover>a {
                background: none;
                color: #ffffff;
            }
        }

        .inside-top-bar {
            padding: 10px;
        }

        .inside-header {
            padding: 40px;
        }

        .site-main .wp-block-group__inner-container {
            padding: 40px;
        }

        .entry-content .alignwide,
        body:not(.no-sidebar) .entry-content .alignfull {
            margin-left: -40px;
            width: calc(100% + 80px);
            max-width: calc(100% + 80px);
        }

        .rtl .menu-item-has-children .dropdown-menu-toggle {
            padding-left: 20px;
        }

        .rtl .main-navigation .main-nav ul li.menu-item-has-children>a {
            padding-right: 20px;
        }

        .site-info {
            padding: 20px;
        }

        @media (max-width:768px) {

            .separate-containers .inside-article,
            .separate-containers .comments-area,
            .separate-containers .page-header,
            .separate-containers .paging-navigation,
            .one-container .site-content,
            .inside-page-header {
                padding: 30px;
            }

            .site-main .wp-block-group__inner-container {
                padding: 30px;
            }

            .site-info {
                padding-right: 10px;
                padding-left: 10px;
            }

            .entry-content .alignwide,
            body:not(.no-sidebar) .entry-content .alignfull {
                margin-left: -30px;
                width: calc(100% + 60px);
                max-width: calc(100% + 60px);
            }
        }

        .one-container .sidebar .widget {
            padding: 0px;
        }

        @media (max-width:768px) {

            .main-navigation .menu-toggle,
            .main-navigation .mobile-bar-items,
            .sidebar-nav-mobile:not(#sticky-placeholder) {
                display: block;
            }

            .main-navigation ul,
            .gen-sidebar-nav {
                display: none;
            }

            [class*="nav-float-"] .site-header .inside-header>* {
                float: none;
                clear: both;
            }
        }

        /*# sourceURL=generate-style-inline-css */
    </style>
