                                        sizes="auto, (max-width: 1080px) 100vw, 1080px" /></p>
                                <p>Jangan pertaruhkan dana umat pada pihak yang tidak memiliki pabrik sendiri. Kami
                                    adalah Qoobah, pembuat kubah masjid resmi yang mengelola seluruh proses produksi
                                    dari awal hingga akhir di lantai fabrikasi kami sendiri.</p>
                                <p>Jika Anda sedang mencari pihak yang jual kubah masjid Parigi Moutong dengan standar
                                    kualitas pabrik, desain mewah, serta konstruksi yang aman menghadapi guncangan, kami
                                    adalah jawabannya.</p>
                                <p>Berhentilah membuang waktu dengan perantara karena hanya kami kontraktor kubah masjid
                                    yang memberikan jaminan keaslian material dan garansi resmi hingga puluhan tahun
                                    bagi seluruh jamaah di Parigi Moutong.</p>
                                <h2><strong>Mengapa Memilih Qoobah Sebagai Produsen Utama Anda?</strong></h2>
                                <p>Membeli langsung dari pusat produksi memberikan kepastian yang tidak bisa diberikan
                                    oleh agen atau toko bangunan biasa di wilayah Sulawesi Tengah.</p>
                                <ul>
                                    <li><strong>Produksi Mandiri:</strong> Seluruh panel diproses menggunakan mesin CNC
                                        modern untuk memastikan presisi yang sempurna tanpa celah sedikitpun.</li>
                                    <li><strong>Bebas Perantara:</strong> Kami memastikan harga tangan pertama tetap
                                        kompetitif tanpa tambahan biaya komisi dari pihak ketiga yang tidak perlu.</li>
                                    <li><strong>Garansi Resmi:</strong> Qoobah memberikan sertifikat garansi tertulis
                                        yang mencakup ketahanan warna hingga kekuatan struktur bangunan secara
                                        menyeluruh.</li>
                                    <li><strong>Pengiriman Profesional:</strong> Pengiriman logistik ditangani secara
                                        teliti melewati jalur darat maupun perairan untuk sampai di wilayah Parigi
                                        Moutong dengan aman.</li>
                                </ul>
                                <h2><strong>Bukti Nyata Pengerjaan Qoobah di Wilayah Parigi Moutong</strong></h2>
                                <p>Kepercayaan masyarakat di sepanjang jalur Trans-Sulawesi telah kami buktikan melalui
                                    berbagai proyek pemasangan yang berdiri kokoh dan menjadi kebanggaan warga setempat:
                                </p>
