                                <p style="padding-left: 40px;">Anda bisa melihat sendiri bagaimana pesanan dikerjakan di
                                    pabrik kami tanpa harus meninggalkan kesibukan di Aceh Timur.</p>
                                <p style="padding-left: 40px;">Transparansi ini kami berikan agar kepercayaan yang
                                    diberikan panitia tetap terjaga dari awal kontrak hingga proses serah terima
                                    pekerjaan selesai.</p>
                                <h2><strong>Desain Modern yang Menjadi Kebanggaan Masyarakat</strong></h2>
                                <p>Arsitektur masjid di wilayah Aceh memiliki ciri khas yang kuat namun tetap terbuka
                                    pada sentuhan modern. Qoobah menghadirkan model Madinah yang elegan atau model
                                    Bawang yang klasik dengan motif warna yang bisa disesuaikan.</p>
                                <p>Tim arsitek kami sanggup mewujudkan visualisasi tiga dimensi sehingga panitia
                                    mendapatkan gambaran pasti sebelum produksi dimulai. Hal ini penting agar tidak ada
                                    kekecewaan setelah barang terpasang.</p>
                                <p>Kesalahan desain di awal hanya akan memicu pemborosan dana masjid yang seharusnya
                                    bisa digunakan untuk keperluan sosial lainnya.</p>
                                <p>Kami teringat salah satu proyek kami di wilayah Aceh Timur beberapa waktu lalu.
                                    Panitia awalnya ragu memilih motif warna hijau tua, namun setelah kami berikan
