                                <h3 style="padding-left: 40px;"><strong>1. Jaminan Garansi Resmi Tertulis</strong></h3>
                                <p style="padding-left: 40px;">Kami memberikan garansi tertulis hingga 20 tahun untuk
                                    ketahanan warna enamel. Ini bukan sekadar janji lisan.</p>
                                <p style="padding-left: 40px;">Jika terjadi kerusakan warna atau kebocoran sesuai masa
