                                <p style="padding-left: 40px;">Proses pemasangan di lapangan dilakukan dengan ketelitian
                                    ekstra untuk memastikan struktur rangka benar-benar simetris dan aman dari risiko
                                    roboh saat cuaca buruk melanda.</p>
                                <p style="padding-left: 40px;">Pengalaman kami selama bertahun-tahun dalam menangani
                                    berbagai ukuran kubah membuat kami sanggup mengatasi segala hambatan teknis di
                                    lokasi proyek.</p>
                                <h3 style="padding-left: 40px;"><strong>3. Konsultasi Gratis dan Survei Lokasi</strong>
                                </h3>
                                <p style="padding-left: 40px;">Kami menyediakan layanan konsultasi tanpa biaya untuk
                                    membantu pengurus menentukan ukuran yang proporsional.</p>
                                <p style="padding-left: 40px;">Tim kami juga bisa melakukan survei lapangan untuk
                                    memastikan kesiapan pondasi masjid sebelum kubah besar diletakkan</p>
                                <p style="padding-left: 40px;">Hal ini untuk menghindari risiko struktur bangunan utama
                                    yang retak akibat beban yang terlalu berat.</p>
                                <h2><strong>Harga Kubah Masjid di Idi Rayeuk yang Transparan</strong></h2>
                                <p>Banyak vendor di luar sana memberikan harga murah namun secara diam-diam menurunkan
                                    spesifikasi material yang dijanjikan. Hal ini tentu sangat merugikan pihak panitia
                                    yang sudah bersusah payah mengumpulkan dana dari masyarakat.</p>
