                                        sizes="auto, (max-width: 1080px) 100vw, 1080px" /></figure>
                                <p style="margin-bottom: 6pt;">Jangan tunda lagi pengerjaan masjid kebanggaan Anda di
                                    Bumi Syekh Hamzah Fansuri. Segera hubungi tim ahli kami karena kami jual kubah
                                    masjid Subulussalam langsung dari pabrik PT Anugerah Kubah Indonesia.</p>
                                <p style="margin-bottom: 6pt;">Kami adalah produsen dan pembuat kubah masjid spesialis
                                    panel yang memproduksi setiap detail rangka serta atap secara mandiri di workshop
                                    sendiri. Jangan ambil risiko dengan vendor tidak jelas yang hanya menjadi perantara.
                                </p>
