                                    pihak lain. Semua proses produksi kubah pesanan Anda dilakukan di pabrik kami di
                                    Kediri, Jawa Timur.</p>
                                <p style="margin-bottom: 6pt; margin-left: 28.35pt;">Dengan sistem manajemen mutu yang
                                    ketat, setiap potongan panel presisi hingga milimeter.</p>
                                <p style="margin-bottom: 6pt; margin-left: 28.35pt;">Hal ini memastikan proses
                                    pemasangan di Subulussalam nantinya berjalan mulus tanpa kendala teknis yang
                                    merugikan waktu panitia.</p>
                                <h3 style="padding-left: 40px;"><strong><span style="color: #000000;">2.
                                            Legalitas</span></strong><strong><span style="color: #000000;"> PT
                                        </span></strong><strong><span style="color: #000000;">Anugerah</span></strong>
                                    <strong><span style="color: #000000;">Kubah</span></strong><strong><span
                                            style="color: #000000;"> Indonesia yang </span></strong><strong><span
                                            style="color: #000000;">Jelas</span></strong>
                                </h3>
                                <p style="margin-bottom: 6pt; margin-left: 28.35pt;">Bekerja sama dengan kami berarti
                                    Anda mendapatkan jaminan keamanan transaksi. Kami bukan individu atau bengkel las
                                    kecil, melainkan perusahaan berbadan hukum tetap.</p>
                                <p style="margin-bottom: 6pt; margin-left: 28.35pt;">Transparansi administrasi dan
                                    kontrak kerja yang kuat menjadi prioritas agar semua pihak merasa tenang.</p>
                                <h3 style="padding-left: 40px;"><strong><span style="color: #000000;">3.
                                            Laporan</span></strong><strong><span style="color: #000000;"> Progress
                                        </span></strong><strong><span
                                            style="color: #000000;">Transparan</span></strong><strong><span
                                            style="color: #000000;"> dan </span></strong><strong><span
                                            style="color: #000000;">Akuntabel</span></strong></h3>
                                <p style="margin-bottom: 6pt; margin-left: 28.35pt;">Jarak Subulussalam ke pabrik kami
